ITEMS.append({
 "id": "l230-vm-skipper", "title": "Μήνυμα από τον κυβερνήτη του ιστιοφόρου", "title_en": "A message from the skipper of the sailing boat", "type": "voicemail", "level": "B2",
 "context_el": "Έχετε κλείσει με φίλους ένα ιστιοφόρο με κυβερνήτη για μια εβδομάδα. Ακούτε ένα μήνυμα στον τηλεφωνητή σας.",
 "script": [
  L("Κυβερνήτης", "m", "Καλησπέρα, ο Μανώλης είμαι, ο κυβερνήτης του σκάφους που κλείσατε για το Σάββατο. Σας παίρνω για μια αλλαγή στο πρόγραμμα, γιατί είδα την πρόγνωση του καιρού για την ερχόμενη εβδομάδα.", "Good evening, it's Manolis, the skipper of the boat you booked for Saturday. I'm calling about a change in the plan, because I've seen the weather forecast for next week."),
  L("Κυβερνήτης", "m", "Από την Κυριακή αρχίζουν μελτέμια, επτά με οκτώ μποφόρ στις Κυκλάδες, και δεν θέλω να περάσετε την εβδομάδα με ναυτία. Προτείνω λοιπόν, αντί για Κύθνο και Σίφνο, να γυρίσουμε τον Σαρωνικό: Αίγινα, Πόρο, Ύδρα και, αν το επιτρέψει ο καιρός, Σπέτσες. Εκεί η θάλασσα είναι πολύ πιο προστατευμένη.", "From Sunday the meltemi winds start, force seven to eight in the Cyclades, and I don't want you to spend the week seasick. So I suggest that, instead of Kythnos and Sifnos, we go round the Saronic: Aegina, Poros, Hydra and, weather permitting, Spetses. The sea there is much more sheltered."),
  L("Κυβερνήτης", "m", "Δύο πρακτικά ακόμα. Φέρτε μαλακές τσάντες και όχι σκληρές βαλίτσες, γιατί στις καμπίνες δεν χωράνε. Και στείλτε μου μέχρι την Πέμπτη τη λίστα με όσα θέλετε να έχουμε στο σκάφος για πρωινό και μεσημεριανό, για να τα παραγγείλω από το σούπερ μάρκετ της μαρίνας.", "Two more practical things. Bring soft bags and not hard suitcases, because they don't fit in the cabins. And send me by Thursday the list of what you'd like us to have on board for breakfast and lunch, so I can order it from the marina supermarket."),
  L("Κυβερνήτης", "m", "Αν προτιμάτε να κρατήσουμε το αρχικό πρόγραμμα, το συζητάμε, αλλά να ξέρετε ότι μπορεί να μείνουμε δεμένοι στο λιμάνι μία ή δύο μέρες. Πάρτε με όποτε μπορείτε. Καλό βράδυ!", "If you'd rather we kept the original plan, we can discuss it, but be aware that we might stay tied up in port for a day or two. Call me whenever you can. Good night!"),
 ],
 "questions": [
  Q("Γιατί προτείνει ο κυβερνήτης αλλαγή στο πρόγραμμα;", ["Γιατί χάλασε το σκάφος", "Γιατί η πρόγνωση δείχνει δυνατούς ανέμους στις Κυκλάδες", "Γιατί δεν βρήκε θέση στη μαρίνα", "Γιατί είναι άρρωστος"], 1, "Από την Κυριακή αρχίζουν μελτέμια, επτά με οκτώ μποφόρ στις Κυκλάδες"),
  Q("Τι προτείνει αντί για Κύθνο και Σίφνο;", ["Να μείνουν στο λιμάνι όλη την εβδομάδα", "Να πάνε στις Σποράδες", "Να γυρίσουν τα νησιά του Σαρωνικού", "Να μεταφέρουν το ταξίδι έναν μήνα αργότερα"], 2, "Προτείνω … να γυρίσουμε τον Σαρωνικό"),
  Q("Γιατί πρέπει να φέρουν μαλακές τσάντες;", ["Γιατί είναι πιο ελαφριές", "Γιατί οι σκληρές βαλίτσες δεν χωράνε στις καμπίνες", "Γιατί το απαιτεί η εταιρεία", "Γιατί βρέχονται λιγότερο"], 1, "στις καμπίνες δεν χωράνε"),
  Q("Τι πρέπει να στείλουν μέχρι την Πέμπτη;", ["Τα διαβατήριά τους", "Την υπόλοιπη πληρωμή", "Μια λίστα με τρόφιμα για το σκάφος", "Τα ονόματα όλων των επιβατών"], 2, "στείλτε μου μέχρι την Πέμπτη τη λίστα με όσα θέλετε να έχουμε στο σκάφος για πρωινό και μεσημεριανό"),
 ],
 "gloss": {"κυβερνήτης": "κυβερνήτης — skipper, captain", "πρόγνωση": "πρόγνωση — forecast", "μελτέμια": "μελτέμι — meltemi (strong summer north wind in the Aegean)", "μποφόρ": "μποφόρ — Beaufort (wind force)", "ναυτία": "ναυτία — seasickness, nausea", "προστατευμένη": "προστατευμένος — sheltered, protected", "καμπίνες": "καμπίνα — cabin", "μαρίνας": "μαρίνα — marina", "δεμένοι": "δεμένος — tied up, moored"},
})
ITEMS.append({
 "id": "l230-c1-mono-paroimies", "title": "Γιατί οι παροιμίες λένε και το ένα και το αντίθετο", "title_en": "Why proverbs say one thing and its opposite", "type": "monologue", "level": "C1",
 "context_el": "Ακούτε την αρχή μιας διάλεξης για τις παροιμίες σε έναν κύκλο μαθημάτων λαογραφίας.",
 "script": [
  L("Ομιλήτρια", "f", "Ας ξεκινήσουμε με ένα μικρό παράδοξο. Λέμε «Όποιος βιάζεται σκοντάφτει», αλλά λέμε και «Όποιος πρόλαβε τον Κύριο είδε». Λέμε «Κάλλιο αργά παρά ποτέ», αλλά λέμε και ότι πρέπει να σφυρηλατείς το σίδερο όσο είναι ζεστό. Αν οι παροιμίες ήταν κανόνες, θα έπρεπε να τις θεωρήσουμε αντιφατικές και, επομένως, άχρηστες.", "Let's start with a small paradox. We say 'He who hurries stumbles', but we also say 'He who got there first saw the Lord'. We say 'Better late than never', but we also say you should strike while the iron is hot. If proverbs were rules, we would have to consider them contradictory and therefore useless."),
  L("Ομιλήτρια", "f", "Η παροιμιολογία, όμως, η επιστήμη που μελετά τις παροιμίες, μας δείχνει ότι δεν είναι κανόνες αλλά εργαλεία. Η καθεμιά ταιριάζει σε μια συγκεκριμένη περίσταση, και η τέχνη βρίσκεται στο να διαλέξεις τη σωστή παροιμία τη σωστή στιγμή. Γι' αυτό μια παροιμία που λέγεται εκτός πλαισίου συχνά ακούγεται κενή, ενώ μέσα σε μια κουβέντα μπορεί να κλείσει μια διαφωνία με μία φράση.", "Paremiology, however, the science that studies proverbs, shows us that they aren't rules but tools. Each one suits a particular situation, and the art lies in choosing the right proverb at the right moment. That's why a proverb said out of context often sounds empty, whereas within a conversation it can close a disagreement in a single phrase."),
  L("Ομιλήτρια", "f", "Αυτή η δύναμη έχει να κάνει με το κύρος τους. Όποιος λέει μια παροιμία δεν μιλά μόνο εξ ονόματός του· επικαλείται τη φωνή μιας ολόκληρης κοινότητας. Υπάρχει μια γνωστή φράση, που αποδίδεται στον Άγγλο πολιτικό Τζον Ράσελ, ότι η παροιμία είναι «η σοφία των πολλών και το πνεύμα ενός». Κάποιος τη διατύπωσε πρώτος, αλλά την κράτησαν ζωντανή χιλιάδες στόματα.", "This power has to do with their authority. Whoever says a proverb isn't speaking only in their own name; they invoke the voice of an entire community. There's a well-known phrase, attributed to the English politician John Russell, that a proverb is 'the wisdom of many and the wit of one'. Someone phrased it first, but thousands of mouths kept it alive."),
  L("Ομιλήτρια", "f", "Στην Ελλάδα, ο λαογράφος Νικόλαος Πολίτης συγκέντρωσε στις αρχές του εικοστού αιώνα χιλιάδες παροιμίες από όλες τις περιοχές, συχνά σε πολλές παραλλαγές. Και εδώ βρίσκεται το επόμενο δίδαγμα: μια παροιμία δεν έχει ένα «σωστό» κείμενο. Ζει μέσα από τις αλλαγές της, όπως ακριβώς και η γλώσσα που τη γέννησε.", "In Greece, the folklorist Nikolaos Politis collected thousands of proverbs from every region at the beginning of the twentieth century, often in many variants. And here lies the next lesson: a proverb has no single 'correct' text. It lives through its changes, just like the language that gave birth to it."),
 ],
 "questions": [
  Q("Ποιο παράδοξο θέτει η ομιλήτρια στην αρχή;", ["Ότι οι παροιμίες είναι πολύ παλιές", "Ότι πολλές παροιμίες φαίνεται να αντιφάσκουν μεταξύ τους", "Ότι οι νέοι δεν ξέρουν παροιμίες", "Ότι οι παροιμίες δεν μεταφράζονται"], 1, "Αν οι παροιμίες ήταν κανόνες, θα έπρεπε να τις θεωρήσουμε αντιφατικές"),
  Q("Πώς λύνει η παροιμιολογία αυτό το παράδοξο;", ["Δείχνει ότι μόνο μία από κάθε ζευγάρι είναι αυθεντική", "Βλέπει τις παροιμίες ως εργαλεία για συγκεκριμένες περιστάσεις", "Θεωρεί τις παροιμίες αστεία", "Τις κατατάσσει ανά περιοχή"], 1, "δεν είναι κανόνες αλλά εργαλεία. Η καθεμιά ταιριάζει σε μια συγκεκριμένη περίσταση"),
  Q("Από πού αντλεί μια παροιμία το κύρος της;", ["Από τον συγγραφέα της", "Από τα σχολικά βιβλία", "Από το ότι εκφράζει τη φωνή μιας ολόκληρης κοινότητας", "Από την αρχαιότητά της"], 2, "επικαλείται τη φωνή μιας ολόκληρης κοινότητας"),
  Q("Τι συμπέρασμα βγάζει η ομιλήτρια από τη συλλογή του Πολίτη;", ["Ότι οι παροιμίες χάνονται", "Ότι κάθε περιοχή έχει διαφορετικές παροιμίες", "Ότι μια παροιμία δεν έχει ένα μόνο σωστό κείμενο", "Ότι οι περισσότερες παροιμίες είναι αρχαίες"], 2, "μια παροιμία δεν έχει ένα «σωστό» κείμενο. Ζει μέσα από τις αλλαγές της"),
 ],
 "gloss": {"παράδοξο": "παράδοξο — paradox", "σκοντάφτει": "σκοντάφτω — to stumble, trip", "Κάλλιο": "κάλλιο — better (colloquial, in sayings)", "σφυρηλατείς": "σφυρηλατώ — to forge, hammer", "αντιφατικές": "αντιφατικός — contradictory", "παροιμιολογία": "παροιμιολογία — paremiology, the study of proverbs", "περίσταση": "περίσταση — situation, occasion", "πλαισίου": "πλαίσιο — context, frame", "κύρος": "κύρος — authority, prestige", "επικαλείται": "επικαλούμαι — to invoke, appeal to", "διατύπωσε": "διατυπώνω — to formulate, phrase", "λαογράφος": "λαογράφος — folklorist", "παραλλαγές": "παραλλαγή — variant"},
})
ITEMS.append({
 "id": "l230-c1-int-goodhart", "title": "Όταν ο δείκτης γίνεται στόχος: ο νόμος του Γκούντχαρτ", "title_en": "When the measure becomes the target: Goodhart's law", "type": "interview", "level": "C1",
 "context_el": "Μια οικονομολόγος μιλά σε μια ραδιοφωνική εκπομπή για τους αριθμούς με τους οποίους κρίνουμε σχολεία, νοσοκομεία και επιχειρήσεις.",
 "script": [
  L("Δημοσιογράφος", "m", "Ο τίτλος του νέου σας βιβλίου είναι μια φράση που ακούγεται σαν γρίφος: «Όταν ένας δείκτης γίνεται στόχος, παύει να είναι καλός δείκτης». Από πού προέρχεται;", "The title of your new book is a phrase that sounds like a riddle: 'When a measure becomes a target, it ceases to be a good measure.' Where does it come from?"),
  L("Οικονομολόγος", "f", "Η ιδέα ανήκει στον Βρετανό οικονομολόγο Τσαρλς Γκούντχαρτ, που τη διατύπωσε τη δεκαετία του '70 για τη νομισματική πολιτική. Τη σύντομη και πιο γνωστή μορφή της, αυτήν που διαβάσατε, την έδωσε αργότερα μια ανθρωπολόγος, η Μέριλιν Στράθερν. Η ουσία είναι απλή: μόλις οι άνθρωποι ξέρουν ότι θα κριθούν με βάση έναν αριθμό, αρχίζουν να βελτιώνουν τον αριθμό, όχι απαραίτητα αυτό που ο αριθμός υποτίθεται ότι μετράει.", "The idea belongs to the British economist Charles Goodhart, who formulated it in the seventies about monetary policy. Its short and better-known form, the one you read, was given later by an anthropologist, Marilyn Strathern. The essence is simple: as soon as people know they'll be judged on a number, they start improving the number, not necessarily what the number is supposed to measure."),
  L("Δημοσιογράφος", "m", "Μπορείτε να μας δώσετε ένα παράδειγμα;", "Can you give us an example?"),
  L("Οικονομολόγος", "f", "Το πιο διάσημο είναι από το Ανόι, γύρω στο 1902, όταν οι γαλλικές αρχές πλήρωναν μια αμοιβή για κάθε ουρά αρουραίου που τους παρέδιδαν. Πολύ σύντομα εμφανίστηκαν αρουραίοι χωρίς ουρά να τρέχουν στους δρόμους: κάποιοι έκοβαν τις ουρές και άφηναν τα ζώα ελεύθερα να πολλαπλασιαστούν. Πιο κοντά μας, σκεφτείτε ένα τηλεφωνικό κέντρο που κρίνει τους υπαλλήλους από τη διάρκεια των κλήσεων. Οι κλήσεις γίνονται πιο σύντομες, αλλά ο πελάτης ξαναπαίρνει τηλέφωνο, γιατί το πρόβλημά του δεν λύθηκε.", "The most famous is from Hanoi, around 1902, when the French authorities paid a bounty for every rat tail handed in to them. Very soon tailless rats appeared running in the streets: some people were cutting off the tails and letting the animals go free to breed. Closer to home, think of a call centre that judges employees by call length. Calls get shorter, but the customer calls back, because the problem wasn't solved."),
  L("Δημοσιογράφος", "m", "Να σταματήσουμε λοιπόν να μετράμε;", "So should we stop measuring?"),
  L("Οικονομολόγος", "f", "Καθόλου. Χωρίς μετρήσεις θα κρίναμε με βάση την εντύπωση, που είναι πολύ χειρότερη. Η λύση είναι να χρησιμοποιούμε πολλούς δείκτες μαζί, να τους αλλάζουμε κατά διαστήματα και, κυρίως, να μη δένουμε μισθούς και ποινές αυτόματα με έναν μόνο αριθμό. Ο αριθμός πρέπει να είναι η αφετηρία μιας συζήτησης, όχι το τέλος της.", "Not at all. Without measurement we'd judge by impression, which is much worse. The solution is to use many indicators together, to change them from time to time and, above all, not to tie pay and penalties automatically to a single number. The number should be the starting point of a discussion, not its end."),
 ],
 "questions": [
  Q("Τι λέει στην ουσία ο νόμος του Γκούντχαρτ;", ["Ότι οι αριθμοί δεν λένε ποτέ ψέματα", "Ότι όταν κρινόμαστε με έναν αριθμό, βελτιώνουμε τον αριθμό και όχι απαραίτητα αυτό που μετράει", "Ότι οι οικονομολόγοι δεν πρέπει να κάνουν προβλέψεις", "Ότι οι δείκτες πρέπει να αλλάζουν κάθε χρόνο"], 1, "αρχίζουν να βελτιώνουν τον αριθμό, όχι απαραίτητα αυτό που ο αριθμός υποτίθεται ότι μετράει"),
  Q("Ποιος έδωσε τη σύντομη, γνωστή μορφή της φράσης;", ["Ο ίδιος ο Γκούντχαρτ", "Μια ανθρωπολόγος, η Μέριλιν Στράθερν", "Οι γαλλικές αρχές στο Ανόι", "Η ίδια η οικονομολόγος"], 1, "Τη σύντομη και πιο γνωστή μορφή της … την έδωσε αργότερα μια ανθρωπολόγος, η Μέριλιν Στράθερν"),
  Q("Τι έγινε στο Ανόι μετά την αμοιβή για τις ουρές των αρουραίων;", ["Οι αρουραίοι εξαφανίστηκαν", "Οι αρχές σταμάτησαν αμέσως την αμοιβή", "Κάποιοι έκοβαν τις ουρές και άφηναν τους αρουραίους ελεύθερους", "Οι κάτοικοι αρνήθηκαν να συμμετάσχουν"], 2, "κάποιοι έκοβαν τις ουρές και άφηναν τα ζώα ελεύθερα να πολλαπλασιαστούν"),
  Q("Τι προτείνει η οικονομολόγος;", ["Να καταργηθούν οι μετρήσεις", "Να κρίνουμε μόνο με βάση την εντύπωση", "Πολλούς δείκτες μαζί, που να αλλάζουν, και όχι αυτόματη σύνδεση με μισθούς", "Έναν μόνο, πιο αυστηρό δείκτη"], 2, "να χρησιμοποιούμε πολλούς δείκτες μαζί, να τους αλλάζουμε κατά διαστήματα και … να μη δένουμε μισθούς και ποινές αυτόματα με έναν μόνο αριθμό"),
 ],
 "gloss": {"γρίφος": "γρίφος — riddle, puzzle", "δείκτης": "δείκτης — indicator, measure", "παύει": "παύω — to cease, stop", "νομισματική πολιτική": "νομισματική πολιτική — monetary policy", "ανθρωπολόγος": "ανθρωπολόγος — anthropologist", "υποτίθεται": "υποτίθεται — is supposed to", "αμοιβή": "αμοιβή — reward, fee, bounty", "αρουραίου": "αρουραίος — rat", "πολλαπλασιαστούν": "πολλαπλασιάζομαι — to multiply, breed", "τηλεφωνικό κέντρο": "τηλεφωνικό κέντρο — call centre", "εντύπωση": "εντύπωση — impression", "κατά διαστήματα": "κατά διαστήματα — from time to time", "αφετηρία": "αφετηρία — starting point"},
})
rnd = random.Random(230)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-230.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
